PARENT = ('Outsourced IT', '/outsourced-it')


def svc(slug, name, **kw):
    d = dict(kind='service', slug=slug, service_name=name, card_kind='Outsourced IT service', card_title=name,
             eyebrow='Outsourced IT', trail=[PARENT, (name, '/' + slug)])
    d.update(kw)
    return d


